// src/ui/utils/jobHelpers.ts
function getJobStatus(job) {
  if (!job.enabled) {
    return { text: "Disabled", icon: "⚪", class: "status-disabled" };
  }
  const latestExecution = job.executions?.[0];
  if (!latestExecution) {
    return { text: "Never run", icon: "❓", class: "status-disabled" };
  }
  switch (latestExecution.status) {
    case "running":
      return { text: "Running", icon: "\uD83D\uDFE1", class: "status-running" };
    case "completed":
      return { text: "Completed", icon: "\uD83D\uDFE2", class: "status-enabled" };
    case "failed":
      return { text: "Failed", icon: "\uD83D\uDD34", class: "status-failed" };
    default:
      return { text: "Unknown", icon: "❓", class: "status-disabled" };
  }
}
function computeSourceName(type, year, quarter, month, day, sourceTypes) {
  const typeLabel = sourceTypes.find((t) => t.value === type)?.label || type;
  const typePart = typeLabel.toLowerCase().replace(/\s+/g, "-");
  const parts = [typePart];
  if (year)
    parts.push(year);
  if (quarter)
    parts.push(`q${quarter}`);
  if (month)
    parts.push(month);
  if (day)
    parts.push(day);
  return parts.join("_");
}
function getLastSuccessTime(job) {
  const lastSuccessfulExecution = job.executions?.find((e) => e.status === "completed");
  return lastSuccessfulExecution ? new Date(lastSuccessfulExecution.completed_at).toLocaleString() : "Never";
}

